@Repository
public class AdminInvoiceRepository {
    private final JdbcClient jdbc;
    public void requireExport(com.thangit.boardinghouse.security.AuthenticatedUser p,Long property){new com.thangit.boardinghouse.security.PropertyAuthorization(jdbc,new com.thangit.boardinghouse.security.SecurityAudit(jdbc)).requireExport(p,property);}
    public void managerCapability(com.thangit.boardinghouse.security.AuthenticatedUser p,long property,String capability){if(p.activeRole()==RoleCode.MANAGER)new com.thangit.boardinghouse.security.PropertyAuthorization(jdbc,new com.thangit.boardinghouse.security.SecurityAudit(jdbc)).require(p,property,com.thangit.boardinghouse.security.PropertyAuthorization.Capability.valueOf(capability));}
    public AdminInvoiceRepository(JdbcClient jdbc){this.jdbc=jdbc;}
    public boolean capability(long user,String permission){if(!List.of("can_issue_invoice","can_record_payment","can_create_adjustment").contains(permission))return false;return jdbc.sql("SELECT "+permission+" FROM accountant_profiles WHERE user_id=:id").param("id",user).query(Boolean.class).optional().orElse(false);}
    public com.thangit.boardinghouse.service.MonthlyBillingService.Plan calculate(com.thangit.boardinghouse.dto.request.invoice.AdminInvoiceRequests.SaveInvoice r,Map<String,Object> c){return new com.thangit.boardinghouse.service.MonthlyBillingService(jdbc).calculate(r,c);}
    public void snapshot(long id,String content,String hash){jdbc.sql("UPDATE invoices SET calculation_snapshot=:content,calculation_hash=:hash WHERE id=:id").param("content",content).param("hash",hash).param("id",id).update();}
    public void recalculate(long id,com.thangit.boardinghouse.dto.request.invoice.AdminInvoiceRequests.SaveInvoice r,BigDecimal subtotal,com.thangit.boardinghouse.service.MonthlyBillingService.Plan plan){jdbc.sql("INSERT INTO invoice_calculation_revisions(invoice_id,version,content,reason) SELECT id,version,COALESCE(calculation_snapshot,'Legacy draft'),:reason FROM invoices WHERE id=:id").param("reason",r.note()).param("id",id).update();jdbc.sql("DELETE FROM invoice_items WHERE invoice_id=:id").param("id",id).update();int order=1;for(var x:plan.items())addItem(id,x.type(),x.type(),x.name(),x.description(),x.quantity(),x.unit(),x.price(),x.amount(),x.source(),x.sourceId(),order++);jdbc.sql("UPDATE invoices SET is_automated=FALSE,subtotal_amount=:subtotal,discount_amount=:discount,total_amount=:total,remaining_amount=:total,note=:note,due_date=:due,version=version+1 WHERE id=:id AND status='DRAFT'").param("subtotal",subtotal).param("discount",r.discountAmount()==null?BigDecimal.ZERO:r.discountAmount()).param("total",subtotal.subtract(r.discountAmount()==null?BigDecimal.ZERO:r.discountAmount())).param("note",r.note()).param("due",r.dueDate()).param("id",id).update();snapshot(id,plan.content(),plan.hash());}
    public void validateIssue(Map<String,Object> i){long c=((Number)i.get("contract_id")).longValue();var contract=contractForRoom(((Number)i.get("room_id")).longValue(),c).orElseThrow();var manual=items(((Number)i.get("id")).longValue()).stream().filter(x->"MANUAL".equals(x.sourceType())).map(x->new com.thangit.boardinghouse.dto.request.invoice.AdminInvoiceRequests.AdditionalItem(x.name(),x.quantity(),x.unit(),x.unitPrice(),x.description())).toList();var request=new com.thangit.boardinghouse.dto.request.invoice.AdminInvoiceRequests.SaveInvoice(((Number)i.get("room_id")).longValue(),c,i.get("billing_period").toString().substring(0,7),com.thangit.boardinghouse.service.RoomLifecycleGuard.date(i.get("period_start_date")),com.thangit.boardinghouse.service.RoomLifecycleGuard.date(i.get("period_end_date")),LocalDate.now(),com.thangit.boardinghouse.service.RoomLifecycleGuard.date(i.get("due_date")),manual,(BigDecimal)i.get("discount_amount"),false,(String)i.get("note"),"ISSUE",((Number)i.get("version")).longValue());var plan=calculate(request,contract);if(i.get("calculation_hash")==null||!plan.hash().equals(i.get("calculation_hash")))throw com.thangit.boardinghouse.service.MonthlyBillingService.fail("INVOICE_CALCULATION_STALE","Nguồn tính đã thay đổi hoặc bản nháp cũ chưa đối soát; tính lại bản nháp trước phát hành.");}
    public void notifyIssued(long id){jdbc.sql("INSERT INTO notifications(user_id,title,content,type,category) SELECT tenant_id,'Hóa đơn thu tiền nội bộ đã phát hành',CONCAT('Hóa đơn ',code,': ',FORMAT(total_amount,0),' VNĐ'),'INVOICE','INVOICE' FROM invoices WHERE id=:id").param("id",id).update();}
    private String scope(RoleCode role,String p){return switch(role){case OWNER->p+".owner_id=:userId";case ACCOUNTANT->"EXISTS(SELECT 1 FROM accountant_property_assignments apa WHERE apa.property_id="+p+".id AND apa.accountant_id=:userId)";default->"EXISTS(SELECT 1 FROM property_managers pm WHERE pm.property_id="+p+".id AND pm.manager_id=:userId AND EXISTS(SELECT 1 FROM manager_property_capabilities mc WHERE mc.property_id=pm.property_id AND mc.manager_id=pm.manager_id AND mc.capability='FINANCE_READ'))";};}
    public boolean canAccess(long userId,RoleCode role,long propertyId){return jdbc.sql("SELECT COUNT(*) FROM properties p WHERE p.id=:id AND "+scope(role,"p")).param("id",propertyId).param("userId",userId).query(Long.class).single()>0;}
    public List<Option> properties(long userId,RoleCode role){return jdbc.sql("SELECT p.id,p.name FROM properties p WHERE "+scope(role,"p")+" ORDER BY p.name").param("userId",userId).query((r,n)->new Option(r.getLong(1),r.getString(2),null)).list();}
    public List<Option> buildings(long userId,RoleCode role){return jdbc.sql("SELECT b.id,b.name,b.property_id FROM buildings b JOIN properties p ON p.id=b.property_id WHERE "+scope(role,"p")+" ORDER BY p.name,b.display_order").param("userId",userId).query((r,n)->new Option(r.getLong(1),r.getString(2),r.getLong(3))).list();}
    public List<Option> floors(long userId,RoleCode role){return jdbc.sql("SELECT f.id,f.name,f.building_id FROM floors f JOIN buildings b ON b.id=f.building_id JOIN properties p ON p.id=b.property_id WHERE "+scope(role,"p")+" ORDER BY b.display_order,f.display_order").param("userId",userId).query((r,n)->new Option(r.getLong(1),r.getString(2),r.getLong(3))).list();}
    public List<Option> rooms(long userId,RoleCode role){return jdbc.sql("SELECT r.id,CONCAT(r.code,' · ',COALESCE(r.name,'')),r.floor_id FROM rooms r JOIN properties p ON p.id=r.property_id WHERE "+scope(role,"p")+" ORDER BY p.name,r.code").param("userId",userId).query((r,n)->new Option(r.getLong(1),r.getString(2),nullableLong(r,3))).list();}
    public List<Option> contracts(long userId,RoleCode role){return jdbc.sql("SELECT c.id,CONCAT(c.code,' · ',u.full_name),c.room_id FROM contracts c JOIN rooms r ON r.id=c.room_id JOIN properties p ON p.id=r.property_id JOIN users u ON u.id=c.tenant_id WHERE c.status IN ('PENDING_CONFIRMATION','ACTIVE','EXPIRING') AND "+scope(role,"p")+" ORDER BY c.code").param("userId",userId).query((r,n)->new Option(r.getLong(1),r.getString(2),r.getLong(3))).list();}

    private record Filter(String where,Map<String,Object> params){}
    private Filter filters(long userId,RoleCode role,Long propertyId,Long buildingId,Long floorId,Long roomId,String keyword,String period,String status,Boolean overdue,BigDecimal min,BigDecimal max){
        StringBuilder w=new StringBuilder(scope(role,"p"));Map<String,Object> x=new HashMap<>();x.put("userId",userId);
        if(propertyId!=null){w.append(" AND p.id=:propertyId");x.put("propertyId",propertyId);}if(buildingId!=null){w.append(" AND r.building_id=:buildingId");x.put("buildingId",buildingId);}if(floorId!=null){w.append(" AND r.floor_id=:floorId");x.put("floorId",floorId);}if(roomId!=null){w.append(" AND r.id=:roomId");x.put("roomId",roomId);}
        if(period!=null&&!period.isBlank()){w.append(" AND DATE_FORMAT(i.billing_period,'%Y-%m')=:period");x.put("period",period);}if(status!=null&&!status.isBlank()){w.append(" AND ").append(effectiveStatus()).append("=:status");x.put("status",status.toUpperCase());}
        if(Boolean.TRUE.equals(overdue))w.append(" AND i.due_date<CURRENT_DATE AND i.remaining_amount>0 AND i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED')");if(min!=null){w.append(" AND i.total_amount>=:minimum");x.put("minimum",min);}if(max!=null){w.append(" AND i.total_amount<=:maximum");x.put("maximum",max);}
        if(keyword!=null&&!keyword.isBlank()){w.append(" AND (LOWER(i.code) LIKE :keyword OR LOWER(r.code) LIKE :keyword OR LOWER(p.name) LIKE :keyword OR LOWER(u.full_name) LIKE :keyword OR LOWER(COALESCE(u.phone,'')) LIKE :keyword OR LOWER(c.code) LIKE :keyword)");x.put("keyword","%"+keyword.trim().toLowerCase()+"%");}return new Filter(w.toString(),x);
    }
    private String effectiveStatus(){return "CASE WHEN i.status IN ('ISSUED','UNPAID','PARTIALLY_PAID') AND i.remaining_amount>0 AND i.due_date<CURRENT_DATE THEN 'OVERDUE' ELSE i.status END";}
    private String joins(){return " FROM invoices i JOIN contracts c ON c.id=i.contract_id JOIN rooms r ON r.id=COALESCE(i.room_id,c.room_id) JOIN properties p ON p.id=r.property_id JOIN users u ON u.id=c.tenant_id LEFT JOIN users cb ON cb.id=i.created_by ";}
    public Summary summary(long userId,RoleCode role,Long propertyId,String period){Filter f=filters(userId,role,propertyId,null,null,null,null,period,null,null,null,null);return jdbc.sql("SELECT COALESCE(SUM(CASE WHEN i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') THEN i.total_amount ELSE 0 END),0) total,COALESCE(SUM(CASE WHEN i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') THEN i.paid_amount ELSE 0 END),0) paid,COALESCE(SUM(CASE WHEN i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') THEN i.remaining_amount ELSE 0 END),0) debt,SUM(i.status='DRAFT') drafts,SUM(i.status IN ('ISSUED','UNPAID')) unpaid,SUM(i.status='PARTIALLY_PAID') partial,SUM(i.status='PAID') paid_count,SUM(i.due_date<CURRENT_DATE AND i.remaining_amount>0 AND i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED')) overdue "+joins()+" WHERE "+f.where()).params(f.params()).query((r,n)->{BigDecimal total=r.getBigDecimal("total"),paid=r.getBigDecimal("paid");return new Summary(total,paid,r.getBigDecimal("debt"),total.signum()==0?BigDecimal.ZERO:paid.multiply(BigDecimal.valueOf(100)).divide(total,2,java.math.RoundingMode.HALF_UP),r.getLong("drafts"),r.getLong("unpaid"),r.getLong("partial"),r.getLong("paid_count"),r.getLong("overdue"));}).single();}
    public Page<InvoiceRow> list(long userId,RoleCode role,Long propertyId,Long buildingId,Long floorId,Long roomId,String keyword,String period,String status,Boolean overdue,BigDecimal min,BigDecimal max,String sort,int page,int size){Filter f=filters(userId,role,propertyId,buildingId,floorId,roomId,keyword,period,status,overdue,min,max);long total=jdbc.sql("SELECT COUNT(*)"+joins()+" WHERE "+f.where()).params(f.params()).query(Long.class).single();String order=switch(sort==null?"":sort){case"oldest"->"i.created_at ASC";case"due"->"i.due_date ASC";case"amount"->"i.total_amount DESC";case"debt"->"i.remaining_amount DESC";default->"i.created_at DESC";};Map<String,Object>x=new HashMap<>(f.params());x.put("limit",size);x.put("offset",page*size);List<InvoiceRow> rows=jdbc.sql("SELECT i.id,i.code,DATE_FORMAT(i.billing_period,'%m/%Y') period,p.id property_id,p.name property_name,r.id room_id,r.code room_code,r.building_name,r.floor_name,u.id tenant_id,u.full_name tenant_name,u.phone,c.id contract_id,c.code contract_code,i.issue_date,i.due_date,i.total_amount,i.paid_amount,i.remaining_amount,"+effectiveStatus()+" effective_status,i.is_automated,i.has_adjustment,i.version,i.created_at,cb.id creator_id,cb.full_name creator_name"+joins()+" WHERE "+f.where()+" ORDER BY "+order+" LIMIT :limit OFFSET :offset").params(x).query((r,n)->row(r)).list();return new Page<>(rows,page,size,total,(int)Math.ceil(total/(double)size));}
    public Optional<Map<String,Object>> invoice(long id,boolean lock){return jdbc.sql("SELECT i.*,p.name property_name,p.address property_address,r.code room_code,r.building_name,r.floor_name,u.full_name tenant_name,u.phone tenant_phone,u.email tenant_email,c.code contract_code,c.start_date contract_start,c.end_date contract_end FROM invoices i JOIN contracts c ON c.id=i.contract_id JOIN rooms r ON r.id=COALESCE(i.room_id,c.room_id) JOIN properties p ON p.id=r.property_id JOIN users u ON u.id=c.tenant_id WHERE i.id=:id"+(lock?" FOR UPDATE":"")).param("id",id).query(AdminInvoiceRepository::map).optional();}
    public Optional<Map<String,Object>> contractForRoom(long roomId,long contractId){return jdbc.sql("SELECT c.*,r.property_id,r.code room_code,c.agreed_monthly_rent monthly_rent,u.full_name tenant_name,u.phone tenant_phone FROM contracts c JOIN rooms r ON r.id=c.room_id JOIN users u ON u.id=c.tenant_id WHERE c.id=:contract AND r.id=:room FOR UPDATE").param("contract",contractId).param("room",roomId).query(AdminInvoiceRepository::map).optional();}
    public Optional<Map<String,Object>> activeContract(long roomId){return jdbc.sql("SELECT c.*,r.property_id,r.code room_code,c.agreed_monthly_rent monthly_rent,u.full_name tenant_name FROM contracts c JOIN rooms r ON r.id=c.room_id JOIN users u ON u.id=c.tenant_id WHERE r.id=:room AND c.status='ACTIVE' AND CURRENT_DATE BETWEEN c.start_date AND c.end_date ORDER BY c.start_date DESC LIMIT 1").param("room",roomId).query(AdminInvoiceRepository::map).optional();}
    public boolean duplicate(long contractId,LocalDate period,Long excluded){return jdbc.sql("SELECT COUNT(*) FROM invoices WHERE contract_id=:contract AND billing_period=:period AND invoice_kind='RENTAL' AND status<>'CANCELLED' AND (:excluded IS NULL OR id<>:excluded)").param("contract",contractId).param("period",period).param("excluded",excluded).query(Long.class).single()>0;}
    public Optional<Map<String,Object>> utility(long contractId,LocalDate period){
        var found=jdbc.sql("SELECT * FROM utility_readings WHERE contract_id=:contract AND billing_period=:period").param("contract",contractId).param("period",period).query(AdminInvoiceRepository::map).optional();
        var baselines=jdbc.sql("SELECT * FROM contract_meter_baselines WHERE contract_id=:id").param("id",contractId).query(AdminInvoiceRepository::map).list();
        var policies=jdbc.sql("SELECT code,calculation_method FROM contract_utility_rates WHERE contract_id=:id").param("id",contractId).query(AdminInvoiceRepository::map).list();
        if(!baselines.isEmpty()&&found.isEmpty())throw new com.thangit.boardinghouse.common.exception.AuthException(org.springframework.http.HttpStatus.CONFLICT,"METER_READING_REQUIRED","Chưa ghi đủ chỉ số điện nước cho kỳ tính tiền.");
        if(found.isEmpty())return found;var reading=new HashMap<>(found.get());
        for(var policy:policies){String prefix="ELECTRICITY".equals(policy.get("code"))?"electricity":"water";
            if("FIXED".equals(policy.get("calculation_method")))reading.put(prefix+"_amount",BigDecimal.ZERO);
            else if(baselines.stream().noneMatch(b->b.get("meter_type").equals(policy.get("code"))))throw new com.thangit.boardinghouse.common.exception.AuthException(org.springframework.http.HttpStatus.CONFLICT,"METER_BASELINE_REQUIRED","Cần mốc bàn giao đã xác nhận trước khi tính tiêu thụ.");
        }
        for(var baseline:baselines){String type=baseline.get("meter_type").toString(),prefix="ELECTRICITY".equals(type)?"electricity":"water";
            long changed=jdbc.sql("SELECT COUNT(*) FROM utility_meter_events WHERE meter_id=:meter AND occurred_at>:at").param("meter",baseline.get("meter_id")).param("at",baseline.get("recorded_at")).query(Long.class).single();
            if(changed>0)throw new com.thangit.boardinghouse.common.exception.AuthException(org.springframework.http.HttpStatus.CONFLICT,"METER_ADJUSTMENT_REVIEW_REQUIRED","Đã có thay/reset đồng hồ sau bàn giao; cần đối soát các đoạn sử dụng trước khi lập hóa đơn.");
            BigDecimal start=new BigDecimal(baseline.get("reading").toString());Object old=reading.get(prefix+"_previous");if(old!=null)start=start.max(new BigDecimal(old.toString()));
            Object current=reading.get(prefix+"_current");if(current==null)throw new com.thangit.boardinghouse.common.exception.AuthException(org.springframework.http.HttpStatus.CONFLICT,"METER_READING_REQUIRED","Thiếu chỉ số cuối kỳ theo hợp đồng.");
            BigDecimal end=new BigDecimal(current.toString());if(end.compareTo(start)<0)throw new com.thangit.boardinghouse.common.exception.AuthException(org.springframework.http.HttpStatus.CONFLICT,"METER_READING_INVALID","Chỉ số cuối thấp hơn mốc đầu kỳ đã xác nhận.");
            BigDecimal price=jdbc.sql("SELECT unit_price FROM contract_utility_rates WHERE contract_id=:id AND code=:type").param("id",contractId).param("type",type).query(BigDecimal.class).single();
            reading.put(prefix+"_previous",start);reading.put(prefix+"_unit_price",price);reading.put(prefix+"_amount",end.subtract(start).multiply(price));
        }
        return Optional.of(reading);
    }
    public List<Map<String,Object>> services(long contractId,LocalDate end){return jdbc.sql("SELECT id,code,name,calculation_method,unit_price FROM contract_services WHERE contract_id=:contract AND effective_date<=:end UNION ALL SELECT id,code,name,calculation_method,unit_price FROM contract_utility_rates WHERE contract_id=:contract AND calculation_method='FIXED' AND effective_date<=:end ORDER BY name").param("contract",contractId).param("end",end).query(AdminInvoiceRepository::map).list();}
    public BigDecimal serviceHeadcount(long contractId,LocalDate end){return jdbc.sql("SELECT GREATEST(1,(SELECT COUNT(DISTINCT tr.tenant_profile_id) FROM tenant_residences tr WHERE tr.contract_id=c.id AND tr.move_in_date<=:end AND (tr.move_out_date IS NULL OR tr.move_out_date>:end))) FROM contracts c WHERE c.id=:id").param("id",contractId).param("end",end).query(BigDecimal.class).single();}
    public BigDecimal previousDebt(long contractId,LocalDate period){return jdbc.sql("SELECT COALESCE(SUM(remaining_amount),0) FROM invoices WHERE contract_id=:contract AND billing_period<:period AND status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED')").param("contract",contractId).param("period",period).query(BigDecimal.class).single();}
    public long createInvoice(long propertyId,long roomId,long contractId,long tenantId,String code,LocalDate period,LocalDate start,LocalDate end,LocalDate issue,LocalDate due,BigDecimal subtotal,BigDecimal discount,BigDecimal debt,BigDecimal lateFee,BigDecimal total,String status,String note,long actor,boolean automated){KeyHolder k=new GeneratedKeyHolder();jdbc.sql("INSERT INTO invoices(property_id,room_id,contract_id,tenant_id,code,billing_period,period_start_date,period_end_date,issue_date,due_date,total_amount,subtotal_amount,discount_amount,previous_debt_amount,late_fee_amount,paid_amount,remaining_amount,status,note,is_automated,created_by,issued_by,issued_at) VALUES(:property,:room,:contract,:tenant,:code,:period,:start,:end,:issue,:due,:total,:subtotal,:discount,:debt,:lateFee,0,:total,:status,:note,:automated,:actor,"+("DRAFT".equals(status)?"NULL,NULL":":actor,CURRENT_TIMESTAMP")+")").param("property",propertyId).param("room",roomId).param("contract",contractId).param("tenant",tenantId).param("code",code).param("period",period).param("start",start).param("end",end).param("issue",issue).param("due",due).param("total",total).param("subtotal",subtotal).param("discount",discount).param("debt",debt).param("lateFee",lateFee).param("status",status).param("note",blank(note)).param("automated",automated).param("actor",actor).update(k,"id");return k.getKey().longValue();}
    public void addItem(long invoiceId,String type,String code,String name,String description,BigDecimal qty,String unit,BigDecimal price,BigDecimal amount,String source,Long sourceId,int order){jdbc.sql("INSERT INTO invoice_items(invoice_id,item_type,item_code,name,description,quantity,unit,unit_price,amount,source_type,source_id,display_order) VALUES(:invoice,:type,:code,:name,:description,:qty,:unit,:price,:amount,:source,:sourceId,:order)").param("invoice",invoiceId).param("type",type).param("code",code).param("name",name).param("description",description).param("qty",qty).param("unit",unit).param("price",price).param("amount",amount).param("source",source).param("sourceId",sourceId).param("order",order).update();}
    public List<Item> items(long id){return jdbc.sql("SELECT * FROM invoice_items WHERE invoice_id=:id ORDER BY display_order,id").param("id",id).query((r,n)->new Item(r.getLong("id"),r.getString("item_type"),r.getString("name"),r.getString("description"),r.getBigDecimal("quantity"),r.getString("unit"),r.getBigDecimal("unit_price"),r.getBigDecimal("amount"),r.getString("source_type"),nullableLong(r,"source_id"))).list();}
    public List<Payment> payments(long id){return jdbc.sql("SELECT py.*,u.full_name FROM payments py LEFT JOIN users u ON u.id=py.received_by WHERE py.invoice_id=:id ORDER BY py.paid_at DESC").param("id",id).query((r,n)->new Payment(r.getLong("id"),r.getString("receipt_code"),r.getBigDecimal("amount"),r.getString("payment_method"),r.getString("reference_code"),r.getString("note"),r.getString("status"),r.getString("full_name"),r.getObject("paid_at",LocalDateTime.class))).list();}
    public List<AdjustmentItem> adjustments(long id){return jdbc.sql("SELECT a.*,u.full_name FROM invoice_adjustments a LEFT JOIN users u ON u.id=a.requested_by WHERE a.invoice_id=:id ORDER BY a.created_at DESC").param("id",id).query((r,n)->new AdjustmentItem(r.getLong("id"),r.getString("adjustment_code"),r.getString("adjustment_type"),r.getBigDecimal("amount"),r.getString("reason"),r.getString("status"),r.getString("full_name"),r.getObject("created_at",LocalDateTime.class))).list();}
    public List<NotificationItem> notifications(long id){return jdbc.sql("SELECT * FROM invoice_notification_logs WHERE invoice_id=:id ORDER BY created_at DESC").param("id",id).query((r,n)->new NotificationItem(r.getLong("id"),r.getString("channel"),r.getString("recipient"),r.getString("status"),r.getObject("sent_at",LocalDateTime.class),r.getObject("created_at",LocalDateTime.class))).list();}
    public List<History> history(long id){return jdbc.sql("SELECT h.*,u.full_name FROM invoice_history h LEFT JOIN users u ON u.id=h.performed_by WHERE h.invoice_id=:id ORDER BY h.created_at DESC").param("id",id).query((r,n)->new History(r.getLong("id"),r.getString("action"),r.getString("previous_status"),r.getString("new_status"),r.getString("reason"),r.getString("full_name"),r.getObject("created_at",LocalDateTime.class))).list();}
    public int issue(long id,long actor,long version){return jdbc.sql("UPDATE invoices SET status='ISSUED',issue_date=COALESCE(issue_date,CURRENT_DATE),issued_by=:actor,issued_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id AND status IN ('DRAFT','PENDING_REVIEW') AND version=:version").param("actor",actor).param("id",id).param("version",version).update();}
    public Optional<Map<String,Object>> paymentByKey(String key){return jdbc.sql("SELECT id,invoice_id,amount,payment_method,reference_code,note,paid_at FROM payments WHERE idempotency_key=:key").param("key",key).query(AdminInvoiceRepository::map).optional();}
    public boolean accountingPeriodLocked(long propertyId,LocalDate date){lockPaymentScope(propertyId);return !jdbc.sql("SELECT id FROM accounting_periods WHERE property_id=:property AND :date BETWEEN start_date AND end_date AND status='CLOSED' FOR UPDATE").param("property",propertyId).param("date",date).query(Long.class).list().isEmpty();}
    public void lockPaymentScope(long propertyId){FinancialPeriodLocks.lock(jdbc,propertyId);jdbc.sql("SELECT id FROM users WHERE id=(SELECT owner_id FROM properties WHERE id=:property) FOR UPDATE").param("property",propertyId).query(Long.class).single();}
    public boolean allowPartial(long propertyId){return jdbc.sql("SELECT COALESCE(b.allow_partial_payment,TRUE) FROM properties p LEFT JOIN billing_settings b ON b.owner_id=p.owner_id WHERE p.id=:property").param("property",propertyId).query(Boolean.class).single();}
    public Optional<Map<String,Object>> paymentByReference(long propertyId,String method,String reference){return jdbc.sql("SELECT py.id,py.invoice_id,py.idempotency_key,py.status FROM payments py JOIN properties p ON p.id=py.property_id WHERE p.owner_id=(SELECT owner_id FROM properties WHERE id=:property) AND py.payment_method=:method AND py.reference_code=:reference UNION ALL SELECT dt.id,NULL,dt.idempotency_key,dt.status FROM deposit_transactions dt JOIN tenant_deposits dd ON dd.id=dt.deposit_id JOIN properties p ON p.id=dd.property_id WHERE p.owner_id=(SELECT owner_id FROM properties WHERE id=:property) AND dt.payment_method=:method AND TRIM(dt.reference_code)=:reference AND dt.transaction_type='COLLECT' LIMIT 1").param("property",propertyId).param("method",method).param("reference",reference.trim()).query(AdminInvoiceRepository::map).optional();}
    public long payment(Map<String,Object> invoice,BigDecimal amount,String method,LocalDateTime paidAt,String reference,String note,String key,long actor){KeyHolder k=new GeneratedKeyHolder();jdbc.sql("INSERT INTO payments(property_id,invoice_id,tenant_id,receipt_code,amount,payment_method,reference_code,reference_dedup_key,idempotency_key,note,transaction_type,status,received_by,paid_at) VALUES(:property,:invoice,:tenant,CONCAT('PT-',REPLACE(UUID(),'-','')),:amount,:method,:reference,CASE WHEN :reference IS NULL THEN NULL ELSE CONCAT((SELECT owner_id FROM properties WHERE id=:property),'|',UPPER(:method),'|',TRIM(:reference)) END,:key,:note,'PAYMENT','CONFIRMED',:actor,:paidAt)").param("property",invoice.get("property_id")).param("invoice",invoice.get("id")).param("tenant",invoice.get("tenant_id")).param("amount",amount).param("method",method).param("reference",blank(reference)).param("key",key).param("note",blank(note)).param("actor",actor).param("paidAt",paidAt).update(k,"id");long paymentId=k.getKey().longValue();jdbc.sql("INSERT INTO payment_allocations(payment_id,invoice_id,amount) VALUES(:payment,:invoice,:amount)").param("payment",paymentId).param("invoice",invoice.get("id")).param("amount",amount).update();return paymentId;}
    public long receipt(long payment,Map<String,Object> invoice,BigDecimal amount,long actor,String note){KeyHolder k=new GeneratedKeyHolder();jdbc.sql("INSERT INTO financial_receipts(receipt_code,payment_id,property_id,tenant_id,amount,issued_by,note) VALUES(CONCAT('BL-',LPAD(:payment,10,'0')),:payment,:property,:tenant,:amount,:actor,:note)").param("payment",payment).param("property",invoice.get("property_id")).param("tenant",invoice.get("tenant_id")).param("amount",amount).param("actor",actor).param("note",blank(note)).update(k,"id");return k.getKey().longValue();}
    public void audit(long property,long actor,long payment,String action,String reason){jdbc.sql("INSERT INTO financial_audit_logs(property_id,actor_id,entity_type,entity_id,action,reason) VALUES(:property,:actor,'PAYMENT',:payment,:action,:reason)").param("property",property).param("actor",actor).param("payment",payment).param("action",action).param("reason",blank(reason)).update();}
    public void notifyPayment(Map<String,Object> invoice,BigDecimal amount){jdbc.sql("INSERT INTO notifications(user_id,title,content,type,category) VALUES(:tenant,'Thanh toán đã được xác nhận',CONCAT('Đã ghi nhận ',FORMAT(:amount,0),' VNĐ cho hóa đơn ',:code),'PAYMENT','PAYMENT')").param("tenant",invoice.get("tenant_id")).param("amount",amount).param("code",invoice.get("code")).update();}
    public int applyPayment(long id,BigDecimal amount,long version){return jdbc.sql("UPDATE invoices SET status=CASE WHEN remaining_amount=:amount THEN 'PAID' ELSE 'PARTIALLY_PAID' END,paid_at=CASE WHEN remaining_amount=:amount THEN CURRENT_TIMESTAMP ELSE paid_at END,paid_amount=paid_amount+:amount,remaining_amount=remaining_amount-:amount,version=version+1 WHERE id=:id AND version=:version AND status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED','PAID') AND remaining_amount>=:amount").param("amount",amount).param("id",id).param("version",version).update();}
    public int cancel(long id,String reason,long actor,long version){return jdbc.sql("UPDATE invoices SET status='CANCELLED',cancelled_by=:actor,cancelled_at=CURRENT_TIMESTAMP,cancellation_reason=:reason,version=version+1 WHERE id=:id AND version=:version AND NOT EXISTS(SELECT 1 FROM contracts c WHERE c.id=invoices.contract_id AND c.financially_closed_at IS NOT NULL) AND paid_amount=0 AND status NOT IN ('PAID','CANCELLED')").param("actor",actor).param("reason",reason).param("id",id).param("version",version).update();}
    public int adjust(long id,String type,BigDecimal amount,String reason,long actor,long version){BigDecimal signed="INCREASE".equals(type)?amount:amount.negate();int n=jdbc.sql("UPDATE invoices SET status=CASE WHEN remaining_amount+:signed=0 THEN 'PAID' WHEN paid_amount>0 THEN 'PARTIALLY_PAID' ELSE 'ISSUED' END,total_amount=total_amount+:signed,remaining_amount=remaining_amount+:signed,has_adjustment=TRUE,version=version+1 WHERE id=:id AND version=:version AND status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') AND NOT EXISTS(SELECT 1 FROM contracts c WHERE c.id=invoices.contract_id AND c.financially_closed_at IS NOT NULL) AND total_amount+:signed>=0 AND remaining_amount+:signed>=0").param("signed",signed).param("id",id).param("version",version).update();if(n>0)jdbc.sql("INSERT INTO invoice_adjustments(invoice_id,adjustment_code,adjustment_type,amount,reason,requested_by,approved_by,approved_at) VALUES(:invoice,CONCAT('DC-',DATE_FORMAT(NOW(),'%Y%m%d'),'-',LPAD(FLOOR(RAND()*999999),6,'0')),:type,:amount,:reason,:actor,:actor,CURRENT_TIMESTAMP)").param("invoice",id).param("type",type).param("amount",amount).param("reason",reason).param("actor",actor).update();return n;}
    public void reminder(long id,String channel,String recipient,long actor){jdbc.sql("INSERT INTO notifications(user_id,title,content,type,category) SELECT tenant_id,'Nhắc thanh toán',CONCAT('Invoice ',code,': ',FORMAT(remaining_amount,0),' VND'),'PAYMENT','PAYMENT' FROM invoices WHERE id=:id").param("id",id).update();jdbc.sql("INSERT INTO invoice_notification_logs(invoice_id,channel,recipient,template_code,status,sent_at,created_by) VALUES(:invoice,:channel,:recipient,'PAYMENT_REMINDER','SENT',CURRENT_TIMESTAMP,:actor)").param("invoice",id).param("channel",channel).param("recipient",recipient).param("actor",actor).update();}
    public void history(long id,String action,String oldStatus,String newStatus,String reason,long actor){jdbc.sql("INSERT INTO invoice_history(invoice_id,action,previous_status,new_status,reason,performed_by) VALUES(:invoice,:action,:old,:new,:reason,:actor)").param("invoice",id).param("action",action).param("old",oldStatus).param("new",newStatus).param("reason",blank(reason)).param("actor",actor).update();}
    public List<Map<String,Object>> roomsForBulk(long propertyId){return jdbc.sql("SELECT r.id,r.code,c.id contract_id,c.tenant_id,c.agreed_monthly_rent monthly_rent,u.full_name tenant_name FROM rooms r JOIN contracts c ON c.room_id=r.id AND c.status='ACTIVE' JOIN users u ON u.id=c.tenant_id WHERE r.property_id=:property AND CURRENT_DATE BETWEEN c.start_date AND c.end_date ORDER BY r.code").param("property",propertyId).query(AdminInvoiceRepository::map).list();}
    private InvoiceRow row(ResultSet r)throws SQLException{LocalDate due=r.getObject("due_date",LocalDate.class);long overdue=due!=null&&due.isBefore(LocalDate.now())&&r.getBigDecimal("remaining_amount").signum()>0?java.time.temporal.ChronoUnit.DAYS.between(due,LocalDate.now()):0;return new InvoiceRow(r.getLong("id"),r.getString("code"),r.getString("period"),new Party(r.getLong("property_id"),r.getString("property_name"),null),new Party(r.getLong("room_id"),r.getString("room_code"),r.getString("building_name")+" · "+r.getString("floor_name")),new Party(r.getLong("tenant_id"),r.getString("tenant_name"),r.getString("phone")),new Party(r.getLong("contract_id"),r.getString("contract_code"),null),r.getObject("issue_date",LocalDate.class),due,r.getBigDecimal("total_amount"),r.getBigDecimal("paid_amount"),r.getBigDecimal("remaining_amount"),overdue,r.getString("effective_status"),nullableLong(r,"creator_id")==null?null:new Party(r.getLong("creator_id"),r.getString("creator_name"),null),r.getBoolean("is_automated"),r.getBoolean("has_adjustment"),r.getLong("version"),r.getObject("created_at",LocalDateTime.class));}
    private static Map<String,Object> map(ResultSet r,int n)throws SQLException{Map<String,Object>x=new HashMap<>();var md=r.getMetaData();for(int i=1;i<=md.getColumnCount();i++)x.put(md.getColumnLabel(i),r.getObject(i));return x;}private static Long nullableLong(ResultSet r,String c)throws SQLException{Object x=r.getObject(c);return x==null?null:((Number)x).longValue();}private static Long nullableLong(ResultSet r,int c)throws SQLException{Object x=r.getObject(c);return x==null?null:((Number)x).longValue();}private static String blank(String x){return x==null||x.isBlank()?null:x.trim();}
}
